
        // ==== CANVAS (new) ====
        string DoCanvas() { var doc = _ghDoc; if (doc == null) return "{\"error\":\"no doc\"}"; try { var comps = new List<object>(); foreach (var obj in doc.Objects) { if (obj is HanakoBridgeComponent) continue; string name = "?"; try { name = obj.NickName ?? obj.GetType().Name; } catch { name = obj.GetType().Name; } string tn = obj.GetType().Name; string g = obj.InstanceGuid.ToString(); double x = 0, y = 0; try { var a = obj.Attributes; if (a != null) { x = a.Pivot.X; y = a.Pivot.Y; } } catch { } var ins = new List<object>(); var outs = new List<object>(); try { var p = obj.GetType().GetProperty("Params").GetValue(obj, null); if (p != null) { dynamic dp = p; var il = (IList)dp.Input; if (il != null) for (int i = 0; i < il.Count; i++) { var pi = (IGH_Param)il[i]; string iname = "?"; try { iname = pi.NickName ?? ("in" + i); } catch { } ins.Add(new { port = i, name = iname, type = pi.TypeName ?? "?", connected = pi.SourceCount > 0 }); } var ol = (IList)dp.Output; if (ol != null) for (int j = 0; j < ol.Count; j++) { var po = (IGH_Param)ol[j]; string oname = "?"; try { oname = po.NickName ?? ("out" + j); } catch { } int tc = 0; foreach (var o2 in doc.Objects) { try { var p2 = o2.GetType().GetProperty("Params").GetValue(o2, null); if (p2 != null) { dynamic dp2 = p2; var i2 = (IList)dp2.Input; if (i2 != null) for (int k = 0; k < i2.Count; k++) { var pi2 = (IGH_Param)i2[k]; if (pi2.SourceCount > 0) for (int s = 0; s < pi2.SourceCount; s++) if (pi2.Sources[s].InstanceGuid == po.InstanceGuid) tc++; } } } catch { } } outs.Add(new { port = j, name = oname, connected = tc > 0, targetCount = tc }); } } } catch { } comps.Add(new { name, type = tn, guid = g, x, y, inputs = ins, outputs = outs }); } return _json.Serialize(new { totalComponents = comps.Count, components = comps }); } catch (Exception ex) { return "canvas err:" + ex.Message; } }

        // ==== EXPLAIN (new) ====
        string DoExplain(string body) { var doc = _ghDoc; if (doc == null) return "no doc"; try { var def = _json.Deserialize<Dictionary<string, object>>(body); var gl = new List<string>(); if (def != null && def.ContainsKey("guids")) { var a = (ArrayList)def["guids"]; foreach (string s in a) gl.Add(s); } if (gl.Count == 0) return "need guids"; var sel = new List<IGH_DocumentObject>(); var sgs = new HashSet<Guid>(); foreach (var o in doc.Objects) { string ig = o.InstanceGuid.ToString(); foreach (var g2 in gl) if (ig.StartsWith(g2)) { sel.Add(o); sgs.Add(o.InstanceGuid); break; } } if (sel.Count == 0) return "no match"; var nm = new Dictionary<Guid, string>(); foreach (var o in sel) { string n = "?"; try { n = o.NickName; if (string.IsNullOrEmpty(n)) n = o.GetType().Name; } catch { n = o.GetType().Name; } nm[o.InstanceGuid] = n; } var sb = new StringBuilder(); sb.Append("选中组件共" + sel.Count + "个。\n"); var ino = new List<string>(); var outo = new List<string>(); foreach (var o in sel) { try { var p = o.GetType().GetProperty("Params").GetValue(o, null); if (p == null) continue; dynamic dp = p; var il = (IList)dp.Input; if (il != null) for (int i = 0; i < il.Count; i++) { var pi = (IGH_Param)il[i]; string pn = "?"; try { pn = pi.NickName ?? ("in" + i); } catch { } if (pi.SourceCount == 0) ino.Add(nm[o.InstanceGuid] + "." + pn + "(未连线)"); else { bool fs = false; for (int s = 0; s < pi.SourceCount; s++) { var sg = pi.Sources[s].InstanceGuid; if (sgs.Contains(sg)) { fs = true; string sn = "?"; foreach (var o2 in doc.Objects) { try { var pp = o2.GetType().GetProperty("Params").GetValue(o2, null); if (pp != null) { dynamic dpp = pp; var ol2 = (IList)dpp.Output; if (ol2 != null) for (int oj = 0; oj < ol2.Count; oj++) if (((IGH_Param)ol2[oj]).InstanceGuid == sg) { try { sn = o2.NickName ?? o2.GetType().Name; } catch { } break; } } } catch { } } sb.Append("  " + sn + ".out → " + nm[o.InstanceGuid] + "." + pn + "\n"); } } if (!fs) { string sn = "外部"; try { var src = pi.Sources[0]; foreach (var o2 in doc.Objects) { try { var pp = o2.GetType().GetProperty("Params").GetValue(o2, null); if (pp != null) { dynamic dpp = pp; var ol2 = (IList)dpp.Output; if (ol2 != null) for (int oj = 0; oj < ol2.Count; oj++) if (((IGH_Param)ol2[oj]).InstanceGuid == src.InstanceGuid) { try { sn = o2.NickName ?? o2.GetType().Name; } catch { } break; } } } catch { } } } catch { } ino.Add(nm[o.InstanceGuid] + "." + pn + "(←" + sn + ")"); } } } var ol3 = (IList)dp.Output; if (ol3 != null) for (int j = 0; j < ol3.Count; j++) { var po = (IGH_Param)ol3[j]; string on = "?"; try { on = po.NickName ?? ("out" + j); } catch { } bool any = false; foreach (var o2 in doc.Objects) { try { var p2 = o2.GetType().GetProperty("Params").GetValue(o2, null); if (p2 != null) { dynamic dp2 = p2; var i2 = (IList)dp2.Input; if (i2 != null) for (int k = 0; k < i2.Count; k++) { var pi2 = (IGH_Param)i2[k]; if (pi2.SourceCount > 0) for (int s = 0; s < pi2.SourceCount; s++) if (pi2.Sources[s].InstanceGuid == po.InstanceGuid) { any = true; break; } } } } catch { } if (any) break; } if (!any) outo.Add(nm[o.InstanceGuid] + "." + on + "(未连线)"); } } catch { } if (ino.Count > 0) { sb.Append("\n外部输入/未连线端口：\n"); foreach (var s in ino) sb.Append("  ◇ " + s + "\n"); } if (outo.Count > 0) { sb.Append("\n外部输出/未连线端口：\n"); foreach (var s in outo) sb.Append("  ◇ " + s + "\n"); } return sb.ToString(); } catch (Exception ex) { return "explain err:" + ex.Message; } }

        // ==== DESCRIBE (new) ====
        string DoDescribe() { try { DoBake(); var rDoc = Rhino.RhinoDoc.ActiveDoc; if (rDoc == null) return _json.Serialize(new { error = "no rhino doc" }); var results = new List<object>(); foreach (var obj in rDoc.Objects) { var geo = obj.Geometry; if (geo == null) continue; var d = new Dictionary<string, object>(); d["type"] = geo.GetType().Name; var bb = geo.GetBoundingBox(true); if (bb.IsValid) { double dx = bb.Max.X - bb.Min.X, dy = bb.Max.Y - bb.Min.Y, dz = bb.Max.Z - bb.Min.Z; d["size"] = new double[] { Math.Round(dx, 2), Math.Round(dy, 2), Math.Round(dz, 2) }; double maxD = Math.Max(dx, Math.Max(dy, dz)); double minD = Math.Min(dx, Math.Min(dy, dz)); if (maxD > minD * 5) d["shape"] = "细长/管状"; else if (maxD < minD * 1.5) d["shape"] = "块状/近立方体"; else d["shape"] = "扁平/片状"; if (maxD > 0.1) { int mainAxis = dx >= dy && dx >= dz ? 0 : (dy >= dz ? 1 : 2); double[] dims = { dx, dy, dz }; int samples = Math.Min(10, Math.Max(3, (int)(dims[mainAxis] / 0.5))); var radii = new List<double>(); for (int s = 0; s <= samples; s++) radii.Add(Math.Round(Math.Sqrt(dims[(mainAxis + 1) % 3] * dims[(mainAxis + 2) % 3] / Math.PI) / 2, 3)); if (radii.Count >= 3 && radii.Average() > 0.001) { double rf = radii[0], rm = radii[radii.Count / 2], rl = radii[radii.Count - 1], avg = radii.Average(); if (Math.Abs(rf - rl) < avg * 0.1) d["taper"] = "等径"; else if (rm > rf * 1.2 && rm > rl * 1.2) d["taper"] = "中间粗两端细"; else if (rf < rl) d["taper"] = "渐粗（单向）"; else d["taper"] = "渐细（单向）"; d["radius_range"] = new double[] { radii.Min(), radii.Max() }; } } } if (geo is Rhino.Geometry.Brep) try { d["volume"] = Math.Round(((Rhino.Geometry.Brep)geo).GetVolume(), 4); } catch { } if (geo is Rhino.Geometry.Mesh) { try { d["vertices"] = ((Rhino.Geometry.Mesh)geo).Vertices.Count; } catch { } try { d["faces"] = ((Rhino.Geometry.Mesh)geo).Faces.Count; } catch { } } if (geo is Rhino.Geometry.Curve) try { d["length"] = Math.Round(((Rhino.Geometry.Curve)geo).GetLength(), 2); } catch { } results.Add(d); } return _json.Serialize(new { total = results.Count, results }); } catch (Exception ex) { return _json.Serialize(new { error = ex.Message }); } }

        // ==== SCREENSHOT (new) ====
        string DoScreenshot() { try { var rDoc = Rhino.RhinoDoc.ActiveDoc; if (rDoc == null) return _json.Serialize(new { error = "no rhino doc" }); var v = rDoc.Views.ActiveView; if (v == null) return _json.Serialize(new { error = "no view" }); var bmp = v.CaptureToBitmap(); if (bmp == null) return _json.Serialize(new { error = "capture failed" }); string p = "D:/agents/-A-hanako/screenshot.png"; bmp.Save(p, System.Drawing.Imaging.ImageFormat.Png); return _json.Serialize(new { ok = true, path = p, width = bmp.Width, height = bmp.Height }); } catch (Exception ex) { return _json.Serialize(new { error = ex.Message }); } }

        // ==== NAME-to-GUID helpers (new) ====
        IGH_DocumentObject TryResolveComponent(string input) { try { var g = new Guid(input); var r = CI(input); if (r != null) return (IGH_DocumentObject)r; } catch { } if (input.Length >= 8) { try { var r = CI(input); if (r != null) return (IGH_DocumentObject)r; } catch { } } if (CompDB != null) { string key = input.ToLowerInvariant(); foreach (var kv in CompDB) { string name = kv.Value; int pipe = name.IndexOf('|'); if (pipe > 0) name = name.Substring(0, pipe); if (name.ToLowerInvariant() == key) { try { return (IGH_DocumentObject)CI(kv.Key); } catch { } } } foreach (var kv in CompDB) { string name = kv.Value; int pipe = name.IndexOf('|'); if (pipe > 0) name = name.Substring(0, pipe); if (name.ToLowerInvariant().Contains(key)) { try { return (IGH_DocumentObject)CI(kv.Key); } catch { } } } } try { var proxy = Grasshopper.Instances.ComponentServer.FindObjectByName(input, true, true); if (proxy != null) { try { return (IGH_DocumentObject)CI(proxy.Guid.ToString().Substring(0, 8)); } catch { } } } catch { } return null; }

        int ResolvePortIndex(object val, Dictionary<string, object> created, string compId, bool isInput) { if (val is int i2) return i2; if (val is long l2) return (int)l2; if (val is double d2) return (int)d2; string name = val.ToString(); if (int.TryParse(name, out int portNum)) return portNum; object compObj = null; if (created.ContainsKey(compId)) compObj = created[compId]; else if (_idMap.ContainsKey(compId)) { var g3 = _idMap[compId]; foreach (var o in _ghDoc.Objects) { if (o.InstanceGuid == g3) { compObj = o; break; } } } if (compObj != null) return FindPortByName((IGH_DocumentObject)compObj, name, isInput); return -1; }

        int ResolvePortOnObject(object val, IGH_DocumentObject obj, bool isInput) { if (val is int i3) return i3; if (val is long l3) return (int)l3; if (val is double d3) return (int)d3; string name = val.ToString(); if (int.TryParse(name, out int portNum)) return portNum; return FindPortByName(obj, name, isInput); }

        int FindPortByName(IGH_DocumentObject obj, string name, bool isInput) { try { if (obj is IGH_Param) { var self = (IGH_Param)obj; return 0; } var p = obj.GetType().GetProperty("Params").GetValue(obj, null); if (p == null) return -1; dynamic dp = p; var list = isInput ? (IList)dp.Input : (IList)dp.Output; if (list == null) return -1; string key = name.ToLowerInvariant(); for (int i = 0; i < list.Count; i++) { var param = (IGH_Param)list[i]; if (param.Name.ToLowerInvariant() == key) return i; if ((param.NickName ?? "").ToLowerInvariant() == key) return i; } for (int i = 0; i < list.Count; i++) { var param = (IGH_Param)list[i]; if (param.Name.ToLowerInvariant().Contains(key)) return i; if ((param.NickName ?? "").ToLowerInvariant().Contains(key)) return i; } } catch { } return -1; }
